[{"order":1,"type":"heading","text":"PHP Data Types"},{"order":2,"type":"paragraph","text":"PHP supports several fundamental data types that determine the kind of values a variable can hold. Understanding these data types is crucial for writing effective and error-free PHP code. This tutorial covers integers, floats, strings, booleans, arrays, objects, resources, and NULL."},{"order":3,"type":"subheading","text":"Integers"},{"order":4,"type":"paragraph","text":"Integers are whole numbers without any decimal part. They can be positive, negative, or zero. The size of an integer depends on the platform, but typically it's a 32-bit or 64-bit value."},{"order":5,"type":"code","text":"<?php
$age = 30; // Positive integer
$quantity = -5; // Negative integer
$count = 0; // Zero integer

var_dump($age); // Output: int(30)
var_dump($quantity); // Output: int(-5)
var_dump($count); // Output: int(0)
?>"},{"order":6,"type":"subheading","text":"Floats (Floating-Point Numbers)"},{"order":7,"type":"paragraph","text":"Floats, also known as floating-point numbers, represent numbers with a decimal part or numbers in exponential form."},{"order":8,"type":"code","text":"<?php
$price = 19.99; // Float with decimal part
$pi = 3.14159; // Another float
$scientific = 1.234E+5; // Float in scientific notation

var_dump($price); // Output: float(19.99)
var_dump($pi); // Output: float(3.14159)
var_dump($scientific); // Output: float(123400)
?>"},{"order":9,"type":"subheading","text":"Strings"},{"order":10,"type":"paragraph","text":"Strings are sequences of characters. They can be enclosed in single quotes (') or double quotes ("). Double quotes allow variable interpolation and escape sequences."},{"order":11,"type":"code","text":"<?php
$name = 'John Doe'; // String with single quotes
$greeting = "Hello, $name!"; // String with double quotes and variable interpolation
$escaped = "This is a \"quoted\" string."; // String with escaped quotes

var_dump($name); // Output: string(8) "John Doe"
var_dump($greeting); // Output: string(13) "Hello, John Doe!"
var_dump($escaped); // Output: string(25) "This is a \"quoted\" string."
?>"},{"order":12,"type":"subheading","text":"Booleans"},{"order":13,"type":"paragraph","text":"Booleans represent truth values: either `true` or `false` (case-insensitive)."},{"order":14,"type":"code","text":"<?php
$is_valid = true;
$is_admin = false;

var_dump($is_valid); // Output: bool(true)
var_dump($is_admin); // Output: bool(false)

if ($is_valid) {
 echo "The value is true.";
}
?>"},{"order":15,"type":"subheading","text":"Arrays"},{"order":16,"type":"paragraph","text":"Arrays are ordered collections of values. Each value in an array is associated with a key, which can be an integer or a string."},{"order":17,"type":"code","text":"<?php
$colors = array("red", "green", "blue"); // Indexed array
$person = array("name" => "Alice", "age" => 25); // Associative array

var_dump($colors); // Output: array(3) { [0]=> string(3) "red" [1]=> string(5) "green" [2]=> string(4) "blue" }
var_dump($person); // Output: array(2) { ["name"]=> string(5) "Alice" ["age"]=> int(25) }

echo $colors[0]; // Output: red
echo $person['name']; // Output: Alice
?>"},{"order":18,"type":"subheading","text":"Objects"},{"order":19,"type":"paragraph","text":"Objects are instances of classes. They encapsulate data (properties) and behavior (methods)."},{"order":20,"type":"code","text":"<?php
class Person {
 public $name;
 public $age;

 public function __construct($name, $age) {
 $this->name = $name;
 $this->age = $age;
 }

 public function greet() {
 return "Hello, my name is " . $this->name . " and I am " . $this->age . " years old.";
 }
}

$person = new Person("Bob", 40);

var_dump($person); // Output: object(Person)#1 (2) { ["name"]=> string(3) "Bob" ["age"]=> int(40) }

echo $person->greet(); // Output: Hello, my name is Bob and I am 40 years old.
?>"},{"order":21,"type":"subheading","text":"Resources"},{"order":22,"type":"paragraph","text":"Resources are special variables that hold references to external resources, such as database connections, file handles, or network sockets. They are typically created by specific functions and must be properly released when no longer needed."},{"order":23,"type":"code","text":"<?php
$file = fopen("data.txt", "r");

var_dump($file); // Output: resource(4) of type (stream)

fclose($file); // Close the resource
?>"},{"order":24,"type":"subheading","text":"NULL"},{"order":25,"type":"paragraph","text":"NULL represents the absence of a value. A variable is NULL if it has been assigned the value NULL, has not been assigned any value yet, or has been unset using the `unset()` function."},{"order":26,"type":"code","text":"<?php
$name = null;
$age;

var_dump($name); // Output: NULL
var_dump($age); // Output: NULL

$city = "New York";
unset($city);
var_dump($city); // Output: NULL
?>"}]
